const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),map=document.querySelector('#map'),mctx=map.getContext('2d');
const W=4400,TAU=Math.PI*2,colors=['#f5b84b','#ff668a','#8e82ff','#46d4b0','#62b9fa','#f58a55','#ca78e9','#dce65e','#54d9d4'];
let vw=innerWidth,vh=innerHeight,dpr=1,camera={x:W/2,y:W/2},snakes=[],food=[],player=null,playing=false,dead=false,last=0,frame=0,pointer={x:vw*.55,y:vh*.52},boost=false,energy=100,best=+(localStorage.getItem('slinkBest')||0),toastTimer=0;
function resize(){vw=innerWidth;vh=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=vw*dpr;canvas.height=vh*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);map.width=map.clientWidth*dpr;map.height=map.clientHeight*dpr;mctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
document.querySelector('#bestStart').textContent=best.toLocaleString();
function rand(a,b){return a+Math.random()*(b-a)}function clamp(x,a,b){return Math.max(a,Math.min(b,x))}function angleDiff(a,b){return Math.atan2(Math.sin(b-a),Math.cos(b-a))}
function addFood(x=rand(110,W-110),y=rand(110,W-110),value=1){food.push({x,y,r:rand(3.2,5.6)+value*.25,value,c:colors[Math.floor(Math.random()*colors.length)],phase:rand(0,TAU)})}
for(let i=0;i<1150;i++)addFood();
function makeSnake(name,color,x,y,ai=false){return{name,color,x,y,angle:rand(0,TAU),path:[{x,y}],length:ai?rand(13,28):10,speed:ai?rand(90,122):145,turn:ai?1.8:2.5,ai,alive:true,boosting:false,think:0,target:rand(0,TAU),score:0,seed:rand(0,TAU)}}
const botNames=['Mochi','Noodle','Pickle','Zippy','Miso','Orbit','Pebble','Kiwi','Bubbles','Sprout','Pesto','Wiggles','Comet','Bean'];
function populateBots(){while(snakes.filter(s=>s.ai).length<14){let n=botNames[Math.floor(Math.random()*botNames.length)];snakes.push(makeSnake(n,colors[Math.floor(Math.random()*colors.length)],rand(140,W-140),rand(140,W-140),true))}}
populateBots();
function startGame(){document.querySelector('#gameover').classList.remove('show');document.querySelector('#start').classList.add('hidden');if(player)snakes=snakes.filter(s=>s!==player);player=makeSnake((document.querySelector('#playerName').value.trim()||'Player').slice(0,14),'#a2f5c7',W/2,W/2,false);player.angle=-Math.PI/2;snakes.push(player);camera.x=player.x;camera.y=player.y;energy=100;playing=true;dead=false;document.querySelector('#score').textContent='10';}
document.querySelector('#play').onclick=startGame;document.querySelector('#again').onclick=startGame;document.querySelector('#playerName').addEventListener('keydown',e=>{if(e.key==='Enter')startGame()});
function setPointer(e){const r=canvas.getBoundingClientRect();pointer.x=e.clientX-r.left;pointer.y=e.clientY-r.top}canvas.addEventListener('pointermove',setPointer);canvas.addEventListener('pointerdown',e=>{setPointer(e);if(e.pointerType==='touch'&&playing)boost=true});canvas.addEventListener('pointerup',()=>boost=false);canvas.addEventListener('pointercancel',()=>boost=false);document.querySelector('#boost').addEventListener('pointerdown',e=>{e.preventDefault();boost=true});for(const ev of ['pointerup','pointercancel','pointerleave'])document.querySelector('#boost').addEventListener(ev,()=>boost=false);addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();boost=true}});addEventListener('keyup',e=>{if(e.code==='Space')boost=false});
function getPoint(s,dist){let traveled=0;for(let i=0;i<s.path.length-1;i++){let a=s.path[i],b=s.path[i+1],dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);if(traveled+d>=dist){let t=(dist-traveled)/(d||1);return{x:a.x+dx*t,y:a.y+dy*t}}traveled+=d}return s.path[s.path.length-1]||{x:s.x,y:s.y}}
function die(s){if(!s.alive)return;s.alive=false;for(let d=0;d<s.length;d+=2){let p=getPoint(s,d*11);for(let k=0;k<2;k++)addFood(p.x+rand(-12,12),p.y+rand(-12,12),2)}if(s===player){playing=false;dead=true;document.querySelector('#finalScore').textContent=Math.floor(s.length);best=Math.max(best,Math.floor(s.length));localStorage.setItem('slinkBest',best);document.querySelector('#bestStart').textContent=best.toLocaleString();setTimeout(()=>document.querySelector('#gameover').classList.add('show'),650)}else setTimeout(()=>{if(snakes.filter(x=>x.ai).length<14)snakes.push(makeSnake(botNames[Math.floor(Math.random()*botNames.length)],colors[Math.floor(Math.random()*colors.length)],rand(160,W-160),rand(160,W-160),true))},2500)}
function eat(s,f){s.length+=f.value*.2;s.score+=f.value;food.splice(food.indexOf(f),1);if(food.length<1200)addFood();if(s===player){document.querySelector('#score').textContent=Math.floor(s.length);const t=document.querySelector('#toast');if(s.length%5<.3){t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),750)}}}
function update(dt){frame++;if(playing&&player?.alive){let wx=pointer.x-vw/2,wy=pointer.y-vh/2;if(Math.hypot(wx,wy)>9){let desired=Math.atan2(wy,wx),d=angleDiff(player.angle,desired);player.angle+=clamp(d,-player.turn*dt,player.turn*dt)}let canBoost=boost&&energy>1&&player.length>7;player.boosting=canBoost;let speed=player.speed*(canBoost?1.8:1);if(canBoost){energy=Math.max(0,energy-30*dt);if(Math.random()<dt*4&&player.length>8){player.length-=.12;let p=getPoint(player,player.length*11);addFood(p.x,p.y,1)}}else energy=Math.min(100,energy+13*dt);document.querySelector('#energy').style.width=energy+'%';player.x+=Math.cos(player.angle)*speed*dt;player.y+=Math.sin(player.angle)*speed*dt;player.x=clamp(player.x,18,W-18);player.y=clamp(player.y,18,W-18);let prev=player.path[0],dist=Math.hypot(player.x-prev.x,player.y-prev.y);if(dist>4)player.path.unshift({x:player.x,y:player.y});player.path.length=Math.min(player.path.length,Math.ceil(player.length*11/4)+40);camera.x+=(player.x-camera.x)*Math.min(1,dt*4);camera.y+=(player.y-camera.y)*Math.min(1,dt*4)}
 for(const s of snakes){if(!s.alive||s===player)continue;s.think-=dt;if(s.think<=0){s.think=rand(.3,1);let nearest=null,nd=1e9;for(const f of food){let d=(f.x-s.x)**2+(f.y-s.y)**2;if(d<nd){nd=d;nearest=f}}if(nearest&&nd<360**2)s.target=Math.atan2(nearest.y-s.y,nearest.x-s.x);else{s.target+=rand(-1.3,1.3)}let edge=Math.min(s.x,s.y,W-s.x,W-s.y);if(edge<280)s.target=Math.atan2(W/2-s.y,W/2-s.x)+rand(-.4,.4)}s.angle+=clamp(angleDiff(s.angle,s.target),-s.turn*dt,s.turn*dt);s.x+=Math.cos(s.angle)*s.speed*dt;s.y+=Math.sin(s.angle)*s.speed*dt;s.x=clamp(s.x,16,W-16);s.y=clamp(s.y,16,W-16);let p=s.path[0];if(Math.hypot(s.x-p.x,s.y-p.y)>4)s.path.unshift({x:s.x,y:s.y});s.path.length=Math.min(s.path.length,Math.ceil(s.length*11/4)+40);}
 if(frame%2===0){for(let i=food.length-1;i>=0;i--){let f=food[i];for(const s of snakes){if(!s.alive)continue;if(Math.hypot(s.x-f.x,s.y-f.y)<13+f.r){eat(s,f);break}}}}
 if(frame%3===0){for(const s of snakes){if(!s.alive)continue;if(s===player&&(s.x<22||s.y<22||s.x>W-22||s.y>W-22)){die(s);continue}for(const o of snakes){if(!o.alive)continue;let start=o===s?5:0;for(let i=start;i<o.length;i+=Math.max(1,Math.floor(o.length/42))){let p=getPoint(o,i*11),d=Math.hypot(s.x-p.x,s.y-p.y);if(d<15){die(s);break}}if(!s.alive)break}}}
 if(player){let rank=1+snakes.filter(s=>s.alive&&s.length>player.length).length;document.querySelector('#rankText').textContent='#'+rank} }

function draw(){ctx.clearRect(0,0,vw,vh);let target=playing&&player?{x:camera.x,y:camera.y}:{x:W/2+Math.sin(frame*.003)*170,y:W/2+Math.cos(frame*.002)*100};let cx=playing?camera.x:target.x,cy=playing?camera.y:target.y;let ox=vw/2-cx,oy=vh/2-cy;ctx.save();ctx.translate(ox,oy);ctx.fillStyle='#0a171c';ctx.fillRect(0,0,W,W);
 // softly illuminated arena and subtle coordinate grid
 let glow=ctx.createRadialGradient(cx,cy,30,cx,cy,Math.max(vw,vh)*.78);glow.addColorStop(0,'#142a2a');glow.addColorStop(.52,'#102326');glow.addColorStop(1,'#0a171c');ctx.fillStyle=glow;ctx.fillRect(Math.max(0,cx-vw),Math.max(0,cy-vh),vw*2,vh*2);
 ctx.lineWidth=1;ctx.strokeStyle='rgba(132,193,169,.055)';let gs=100,fromX=Math.max(0,Math.floor((cx-vw/2)/gs)*gs),toX=Math.min(W,cx+vw/2+gs),fromY=Math.max(0,Math.floor((cy-vh/2)/gs)*gs),toY=Math.min(W,cy+vh/2+gs);ctx.beginPath();for(let x=fromX;x<toX;x+=gs){ctx.moveTo(x,fromY);ctx.lineTo(x,toY)}for(let y=fromY;y<toY;y+=gs){ctx.moveTo(fromX,y);ctx.lineTo(toX,y)}ctx.stroke();
 // arena boundary
 ctx.strokeStyle='#427365';ctx.lineWidth=14;ctx.shadowColor='#65d9ad';ctx.shadowBlur=26;ctx.strokeRect(7,7,W-14,W-14);ctx.shadowBlur=0;ctx.strokeStyle='#8de4b5';ctx.lineWidth=2;ctx.strokeRect(13,13,W-26,W-26);
 // ambient motes
 for(let n=0;n<35;n++){let x=(n*739+Math.sin(frame*.006+n)*40)%W,y=(n*1297+Math.cos(frame*.004+n)*50)%W;if(Math.abs(x-cx)<vw*.65&&Math.abs(y-cy)<vh*.65){ctx.fillStyle='rgba(176,233,200,.22)';ctx.beginPath();ctx.arc(x,y,1.3,0,TAU);ctx.fill()}}
 for(const f of food){if(Math.abs(f.x-cx)>vw*.62||Math.abs(f.y-cy)>vh*.62)continue;let pulse=1+Math.sin(frame*.07+f.phase)*.13;ctx.globalAlpha=.72;ctx.fillStyle=f.c;ctx.shadowColor=f.c;ctx.shadowBlur=11;ctx.beginPath();ctx.arc(f.x,f.y,f.r*pulse,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.globalAlpha=1;ctx.fillStyle='#ffffff';ctx.globalAlpha=.32;ctx.beginPath();ctx.arc(f.x-f.r*.3,f.y-f.r*.35,Math.max(1,f.r*.23),0,TAU);ctx.fill();ctx.globalAlpha=1}
 for(const s of snakes){if(!s.alive||Math.abs(s.x-cx)>vw*.75||Math.abs(s.y-cy)>vh*.75)continue;let count=Math.floor(s.length),spacing=11,r=9;for(let i=count-1;i>=0;i--){let p=getPoint(s,i*spacing);let taper=i>count-4?Math.max(.45,1-(i-(count-4))*.16):1;ctx.beginPath();ctx.fillStyle=s.color;ctx.shadowColor=s.color;ctx.shadowBlur=i===0?14:0;ctx.arc(p.x,p.y,r*taper,0,TAU);ctx.fill()}ctx.shadowBlur=0;let head={x:s.x,y:s.y},eyeDist=4.2,side=4.1;for(let sign of [-1,1]){let ex=head.x+Math.cos(s.angle)*eyeDist+Math.cos(s.angle+Math.PI/2)*side*sign,ey=head.y+Math.sin(s.angle)*eyeDist+Math.sin(s.angle+Math.PI/2)*side*sign;ctx.fillStyle='#f8fff8';ctx.beginPath();ctx.arc(ex,ey,3.2,0,TAU);ctx.fill();ctx.fillStyle='#122522';ctx.beginPath();ctx.arc(ex+Math.cos(s.angle)*1.1,ey+Math.sin(s.angle)*1.1,1.45,0,TAU);ctx.fill()}
 if(s!==player){ctx.font='10px system-ui';ctx.textAlign='center';ctx.fillStyle='rgba(222,239,231,.72)';ctx.fillText(s.name,s.x,s.y-19)}}ctx.restore();drawMap();drawBoard();}
function drawMap(){let w=map.clientWidth,h=map.clientHeight;if(!w||!h)return;mctx.clearRect(0,0,w,h);mctx.fillStyle='#0b1c20';mctx.fillRect(0,0,w,h);mctx.strokeStyle='rgba(152,209,182,.12)';mctx.lineWidth=1;for(let i=1;i<4;i++){mctx.beginPath();mctx.moveTo(w*i/4,0);mctx.lineTo(w*i/4,h);mctx.moveTo(0,h*i/4);mctx.lineTo(w,h*i/4);mctx.stroke()}for(const s of snakes){if(!s.alive)continue;mctx.fillStyle=s===player?'#c3ffdc':s.color;mctx.beginPath();mctx.arc(s.x/W*w,s.y/W*h,s===player?2.8:1.9,0,TAU);mctx.fill()}if(!playing){mctx.strokeStyle='rgba(190,245,211,.3)';mctx.strokeRect(w*.35,h*.35,w*.3,h*.3)}}
function drawBoard(){let active=snakes.filter(s=>s.alive).sort((a,b)=>b.length-a.length).slice(0,5),el=document.querySelector('#leaderboard');el.innerHTML=active.map((s,i)=>`<div class="rank ${s===player?'you':''}"><span class="num">${String(i+1).padStart(2,'0')}</span><i class="dot" style="--c:${s.color}"></i><span class="name">${s===player?'You':s.name}</span><span class="score">${Math.floor(s.length*10)}</span></div>`).join('');}
function loop(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(loop)}
// A lively preview while choosing a name; ambient snakes drift around the arena.
setInterval(()=>{let n=+(document.querySelector('#online').textContent.replace(',',''));document.querySelector('#online').textContent=(n+Math.floor(rand(-5,7))).toLocaleString()},3500);
requestAnimationFrame(loop);
</script></body></html>

