 function rand(a,b){return a+Math.random()*(b-a)}function clamp(x,a,b){return Math.max(a,Math.min(b,x))}function angleDiff(a,b){return Math.atan2(Math.sin(b-a),Math.cos(b-a))}
 function addFood(x=rand(110,W-110),y=rand(110,W-110),value=1){food.push({x,y,r:rand(3.2,5.6)+value*.25,value,c:colors[Math.floor(Math.random()*colors.length)],phase:rand(0,TAU)})}for(let i=0;i<1150;i++)addFood();
-function makeSnake(name,color,x,y,ai=false){return{name,color,x,y,angle:rand(0,TAU),path:[{x,y}],length:ai?rand(13,28):10,speed:ai?rand(90,122):145,turn:ai?1.8:2.5,ai,alive:true,boosting:false,think:0,target:rand(0,TAU),score:0,seed:rand(0,TAU)}}
+function makeSnake(name,color,x,y,ai=false){let angle=rand(0,TAU),length=ai?rand(13,28):10,path=[];for(let d=0;d<=length*11;d+=4)path.push({x:x-Math.cos(angle)*d,y:y-Math.sin(angle)*d});return{name,color,x,y,angle,path,length,speed:ai?rand(90,122):145,turn:ai?1.8:2.5,ai,alive:true,boosting:false,think:0,target:rand(0,TAU),score:0,seed:rand(0,TAU)}}
 const botNames=['Mochi','Noodle','Pickle','Zippy','Miso','Orbit','Pebble','Kiwi','Bubbles','Sprout','Pesto','Wiggles','Comet','Bean'];
 function populateBots(){while(snakes.filter(s=>s.ai).length<14){let n=botNames[Math.floor(Math.random()*botNames.length)];snakes.push(makeSnake(n,colors[Math.floor(Math.random()*colors.length)],rand(W/2-900,W/2+900),rand(W/2-650,W/2+650),true))}}populateBots();
 function getPoint(s,dist){let traveled=0;for(let i=0;i<s.path.length-1;i++){let a=s.path[i],b=s.path[i+1],dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);if(traveled+d>=dist){let t=(dist-traveled)/(d||1);return{x:a.x+dx*t,y:a.y+dy*t}}traveled+=d}return s.path[s.path.length-1]||{x:s.x,y:s.y}}
 function startGame(){document.querySelector('#gameover').classList.remove('show');document.querySelector('#start').classList.add('hidden');if(player)snakes=snakes.filter(s=>s!==player);player=makeSnake((document.querySelector('#playerName').value.trim()||'Player').slice(0,14),'#a2f5c7',W/2,W/2,false);player.angle=-Math.PI/2;snakes.push(player);camera.x=player.x;camera.y=player.y;energy=100;playing=true;dead=false;document.querySelector('#score').textContent='10'}
